"""Per-agent workspaces of the builder service.

Every agent the builder serves lives in its own folder under a shared workspaces
root, with its own git repository and its own `ProjectGenerator`. The agent id
comes from Studio; the builder only checks that it is a safe folder name.

The agent's folder is the checkout of its `main` branch. Every other branch of
the agent gets its own checkout, a git worktree under
`<root>/.worktrees/<agentId>/`, created the first time a request asks for that
branch. A worktree is only a cache of its branch: it can be deleted and is
recreated from the branch on the next request.
"""

import re
import subprocess
from pathlib import Path
from typing import Dict, Optional, Tuple
from urllib.parse import quote

import structlog
from pydantic import BaseModel, ConfigDict
from sanic import Request

from rasa.builder.constants import HEADER_AGENT_ID, HEADER_BRANCH
from rasa.builder.exceptions import (
    BranchNotFoundError,
    InvalidAgentIdError,
    InvalidBranchNameError,
)
from rasa.builder.git_service import GitService
from rasa.builder.project_generator.project_generator import ProjectGenerator

structlogger = structlog.get_logger()

# An agent id becomes a folder name, so it must be exactly one safe path
# segment: no separators, and it cannot be `.` or `..` since it starts with an
# alphanumeric character.
_AGENT_ID_PATTERN = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]{0,127}")

# The branch whose checkout is the agent's own folder.
DEFAULT_BRANCH = "main"

# A subset of git's ref name rules (`git check-ref-format --branch`) that also
# keeps a branch name from ever reading as a command line option: it starts
# with a letter or digit and has no `..`, `//`, `/.`, `@{`, or trailing `/`,
# `.` or `.lock`.
_BRANCH_NAME_PATTERN = re.compile(
    r"(?!.*\.\.)(?!.*//)(?!.*/\.)(?!.*@\{)(?!.*\.lock$)(?!.*[/.]$)"
    r"[A-Za-z0-9][A-Za-z0-9._/-]{0,199}"
)

# Folder under the workspaces root holding the checkouts of non-default
# branches. It can't clash with an agent folder: agent ids start with a letter
# or digit.
WORKTREES_FOLDER = ".worktrees"


class Workspace(BaseModel):
    """One agent's folder together with the generator operating on it."""

    model_config = ConfigDict(frozen=True, arbitrary_types_allowed=True)

    agent_id: str
    branch: str
    path: Path
    project_generator: ProjectGenerator

    @property
    def git_service(self) -> GitService:
        """The git service of the agent's repository."""
        return self.project_generator.git_service


class WorkspaceManager:
    """Create and cache one workspace per agent id under a shared root."""

    def __init__(self, root: Path) -> None:
        """Initialise the manager.

        Args:
            root: Folder holding one sub-folder per agent. Created if missing.
        """
        self.root = root.resolve()
        self.root.mkdir(parents=True, exist_ok=True)
        self._workspaces: Dict[Tuple[str, str], Workspace] = {}

    def get(self, agent_id: str) -> Optional[Workspace]:
        """Return the main workspace of an existing agent without creating one.

        An agent whose folder exists on disk but has not been used since the
        service started is opened and cached.

        Args:
            agent_id: Id of the agent.

        Returns:
            The agent's main workspace, or `None` if the agent has no folder yet.

        Raises:
            InvalidAgentIdError: If `agent_id` is not a valid agent id.
        """
        validate_agent_id(agent_id)
        if (workspace := self._workspaces.get((agent_id, DEFAULT_BRANCH))) is not None:
            return workspace
        if not (self.root / agent_id).is_dir():
            return None
        return self._open_main(agent_id)

    def get_or_create(self, agent_id: str, branch: str = DEFAULT_BRANCH) -> Workspace:
        """Return the workspace of an agent's branch, creating it on first use.

        The main workspace is created with the agent's folder and repository.
        Any other branch must already exist in the agent's repository; its
        checkout is added on first use and re-added if its folder disappeared.

        Deliberately synchronous: without an `await` there is no point where a
        second request for the same checkout could interleave and build a
        second generator, and with it a second git lock, for the same folder.

        Args:
            agent_id: Id of the agent.
            branch: Name of the branch.

        Returns:
            The workspace of the agent's branch.

        Raises:
            InvalidAgentIdError: If `agent_id` is not a valid agent id.
            InvalidBranchNameError: If `branch` is not a valid branch name.
            BranchNotFoundError: If the agent has no branch named `branch`.
        """
        validate_agent_id(agent_id)
        validate_branch_name(branch)
        workspace = self._workspaces.get((agent_id, branch))
        if workspace is not None and workspace.path.is_dir():
            return workspace

        main = self._workspaces.get((agent_id, DEFAULT_BRANCH))
        if main is None:
            main = self._open_main(agent_id)
        if branch == DEFAULT_BRANCH:
            return main
        return self._open_branch(main, branch)

    def _open_main(self, agent_id: str) -> Workspace:
        """Build, cache and return the main workspace of a validated agent id.

        The folder gets its own git repository right away. Without one, git
        commands run in the folder would walk up and operate on whatever
        repository encloses the workspaces root.
        """
        path = self.root / agent_id
        path.mkdir(parents=True, exist_ok=True)
        project_generator = ProjectGenerator(str(path))
        project_generator.git_service.init_repo()

        workspace = Workspace(
            agent_id=agent_id,
            branch=DEFAULT_BRANCH,
            path=path,
            project_generator=project_generator,
        )
        self._workspaces[(agent_id, DEFAULT_BRANCH)] = workspace
        structlogger.info("builder.workspace.opened", agent_id=agent_id, path=str(path))
        return workspace

    def _open_branch(self, main: Workspace, branch: str) -> Workspace:
        """Check out an existing branch of an agent and cache its workspace."""
        if not _branch_exists(main.path, branch):
            raise BranchNotFoundError(
                f"Agent '{main.agent_id}' has no branch named '{branch}'."
            )

        path = branch_checkout_path(self.root, main.agent_id, branch)
        if not path.is_dir():
            # Forget checkouts whose folder is gone, otherwise git refuses to
            # add a new one for the same branch.
            _run_git(main.path, ["worktree", "prune"])
            path.parent.mkdir(parents=True, exist_ok=True)
            _run_git(main.path, ["worktree", "add", str(path), branch])

        workspace = Workspace(
            agent_id=main.agent_id,
            branch=branch,
            path=path,
            project_generator=ProjectGenerator(str(path)),
        )
        self._workspaces[(main.agent_id, branch)] = workspace
        structlogger.info(
            "builder.workspace.branch_opened",
            agent_id=main.agent_id,
            branch=branch,
            path=str(path),
        )
        return workspace


def workspace_folder(root: Path, agent_id: str, branch: str) -> Path:
    """Return the folder of an agent's branch checkout, whether or not it exists.

    Args:
        root: The workspaces root.
        agent_id: A valid agent id.
        branch: A valid branch name.
    """
    if branch == DEFAULT_BRANCH:
        return root / agent_id
    return branch_checkout_path(root, agent_id, branch)


def branch_checkout_path(root: Path, agent_id: str, branch: str) -> Path:
    """Return where the checkout of a non-default branch of an agent lives.

    The branch name is percent-encoded into a single folder name, so `a/b`
    and `a_b` never share a folder.
    """
    return root / WORKTREES_FOLDER / agent_id / quote(branch, safe="")


def validate_branch_name(branch: str) -> None:
    """Raise `InvalidBranchNameError` unless `branch` is a safe branch name."""
    if not _BRANCH_NAME_PATTERN.fullmatch(branch):
        raise InvalidBranchNameError(
            f"'{branch}' is not a valid branch name: use up to 200 letters, "
            "digits, '.', '_', '-' or '/', starting with a letter or digit."
        )


def _branch_exists(repo: Path, branch: str) -> bool:
    """Return whether the repository at `repo` has a local branch `branch`."""
    result = subprocess.run(
        ["git", "rev-parse", "--verify", "--quiet", f"refs/heads/{branch}"],
        cwd=repo,
        capture_output=True,
        text=True,
    )
    return result.returncode == 0


def _run_git(repo: Path, args: list[str]) -> None:
    """Run a git command in `repo`, raising `CalledProcessError` on failure."""
    subprocess.run(["git", *args], cwd=repo, check=True, capture_output=True)


def validate_agent_id(agent_id: str) -> None:
    """Raise `InvalidAgentIdError` unless `agent_id` is a safe folder name."""
    if not _AGENT_ID_PATTERN.fullmatch(agent_id):
        raise InvalidAgentIdError(
            "Agent id must be 1-128 characters of letters, digits, '_' or '-', "
            "starting with a letter or digit."
        )


def resolve_workspace(request: Request) -> Workspace:
    """Return the workspace of the agent and branch the request names.

    The agent comes from the `X-Agent-Id` header and the branch from the
    optional `X-Branch` header (`main` when absent). The main workspace is
    created on the first request for an agent, a branch checkout on the first
    request for that branch.

    Args:
        request: The incoming request.

    Returns:
        The workspace of the requested agent's branch.

    Raises:
        InvalidAgentIdError: If the agent header is missing, empty or not a
            valid agent id.
        InvalidBranchNameError: If the branch header is not a valid branch name.
        BranchNotFoundError: If the agent has no such branch.
    """
    branch = request.headers.get(HEADER_BRANCH) or DEFAULT_BRANCH
    return request.app.ctx.workspace_manager.get_or_create(
        _request_agent_id(request), branch
    )


def resolve_main_workspace(request: Request) -> Workspace:
    """Return the main workspace of the agent named by the `X-Agent-Id` header.

    Ignores the `X-Branch` header, for work that always happens on `main`.

    Raises:
        InvalidAgentIdError: If the header is missing, empty or not a valid
            agent id.
    """
    return request.app.ctx.workspace_manager.get_or_create(_request_agent_id(request))


def _request_agent_id(request: Request) -> str:
    """Return the `X-Agent-Id` header, raising `InvalidAgentIdError` if absent."""
    agent_id = request.headers.get(HEADER_AGENT_ID)
    if not agent_id:
        raise InvalidAgentIdError(f"Missing required header: {HEADER_AGENT_ID}")
    return agent_id
